import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Derived-Artifact Cache and Compression","description":"","frontmatter":{"title":"Derived-Artifact Cache and Compression","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed\\n\\nDepends on [ADR-0063 — Scheme-Core Completeness](./0063-scheme-core-completeness.md)\\nand [ADR-0064 — Computational Language Authoring](./0064-computational-language-authoring.md).\\nRefines [ADR-0044 — Language as Data and Runtime\\nSplit](./0044-language-as-data-and-runtime-split.md) §6 (fragment sources and\\nkit assembly)."},"headers":[],"relativePath":"handl/project/adrs/0065-derived-artifact-cache-and-compression.md","filePath":"vendored/handl/project/adrs/0065-derived-artifact-cache-and-compression.md"}`),a={name:`handl/project/adrs/0065-derived-artifact-cache-and-compression.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0065-derived-artifact-cache-and-compression" tabindex="-1">ADR-0065: Derived-Artifact Cache and Compression <a class="header-anchor" href="#adr-0065-derived-artifact-cache-and-compression" aria-label="Permalink to “ADR-0065: Derived-Artifact Cache and Compression”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-cache-the-merged-language-not-the-authoring-source" tabindex="-1">1. Cache the merged <code>Language</code>, not the authoring source <a class="header-anchor" href="#_1-cache-the-merged-language-not-the-authoring-source" aria-label="Permalink to “1. Cache the merged Language, not the authoring source”">​</a></h3><p>The cache stores the <strong>output of the assembly pipeline</strong>: the merged, validated <code>Language</code> value, serialized (serde). The input is the full set of fragment sources + kit manifest + <code>extends</code> chain + engine selections. The cache does not store intermediate fragments or the authoring program; it stores the final product.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>cache key → serialized merged Language (optionally compressed)</span></span></code></pre></div><h3 id="_2-cache-key-is-a-hash-of-the-full-assembly-input" tabindex="-1">2. Cache key is a hash of the full assembly input <a class="header-anchor" href="#_2-cache-key-is-a-hash-of-the-full-assembly-input" aria-label="Permalink to “2. Cache key is a hash of the full assembly input”">​</a></h3><p>The cache key is a cryptographic hash (BLAKE3) of a canonical serialization of:</p><ol><li>Every fragment source (YAML file content hash, or handl program content hash + the <code>Language</code> used to eval it).</li><li>The kit manifest (ordered fragment-source list + include/exclude filters).</li><li>The <code>extends</code> chain (transitive: parent kits&#39; manifests, recursively).</li><li>Engine selections (lex/parse/eval engine names + versions, per ADR-0044 §7 &quot;Engine selection as data&quot;).</li><li>The <code>scheme_version</code> declared by the <code>Language</code> (ADR-0044 §7).</li></ol><p>If any input changes, the hash changes, and the cache misses. This is the only correct cache key. Hashing a subset (e.g., only the top-level manifest) risks stale hits when a transitive dependency changes.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>key = blake3(canonical_serialize(</span></span>
<span class="line"><span>    fragment_source_hashes,</span></span>
<span class="line"><span>    kit_manifest,</span></span>
<span class="line"><span>    extends_chain_transitive,</span></span>
<span class="line"><span>    engine_selections,</span></span>
<span class="line"><span>    scheme_version,</span></span>
<span class="line"><span>))</span></span></code></pre></div><h3 id="_3-compression-is-applied-to-the-cache-payload-not-the-source" tabindex="-1">3. Compression is applied to the cache payload, not the source <a class="header-anchor" href="#_3-compression-is-applied-to-the-cache-payload-not-the-source" aria-label="Permalink to “3. Compression is applied to the cache payload, not the source”">​</a></h3><p>The serialized merged <code>Language</code> is compressed with zstd before storage. Decompression happens on cache hit. The authored source (YAML, handl program) is never compressed by this system — it remains text on disk.</p><p>Compression level is configurable. Default: level 3 (fast, ~2x compression). Constrained targets may use level 9 (~4x, slower decompression). The tradeoff is I/O cost vs CPU cost, and it is a runtime config, not a build decision.</p><h3 id="_4-cache-invalidation-is-by-key-not-by-ttl" tabindex="-1">4. Cache invalidation is by key, not by TTL <a class="header-anchor" href="#_4-cache-invalidation-is-by-key-not-by-ttl" aria-label="Permalink to “4. Cache invalidation is by key, not by TTL”">​</a></h3><p>There is no time-based expiry. The cache is valid as long as the key matches. If the assembly input changes, the key changes, and the old entry is a miss (not a stale hit). This is correct because the assembly is a pure function of its inputs — same inputs, same output; different inputs, different output.</p><p>TTL-based invalidation is explicitly rejected: it introduces a window where the cache is stale but the key has not changed (e.g., a file was edited but the TTL has not expired). This is the silent-drift failure mode.</p><h3 id="_5-cache-storage-is-pluggable" tabindex="-1">5. Cache storage is pluggable <a class="header-anchor" href="#_5-cache-storage-is-pluggable" aria-label="Permalink to “5. Cache storage is pluggable”">​</a></h3><p>The cache backend is a trait, not a fixed implementation:</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">pub</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> trait</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> LanguageCache</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> {</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">    fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> get</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">&amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#005CC5;--shiki-light-font-style:inherit;">self</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> key</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">CacheKey</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Option</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">CachedLanguage</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&gt;;</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">    fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> put</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">&amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#005CC5;--shiki-light-font-style:inherit;">self</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> key</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">CacheKey</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> lang</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">CachedLanguage</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Result</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;()&gt;;</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">}</span></span></code></pre></div><p>Implementations:</p><ul><li><code>NoCache</code> — always misses (default for compile-time-embedded kits).</li><li><code>InMemoryCache</code> — <code>HashMap&lt;CacheKey, CachedLanguage&gt;</code>, process-lifetime.</li><li><code>OnDiskCache</code> — files in a cache directory, persistent across runs.</li><li>(future) <code>NetworkCache</code> — shared cache for a fleet of hosts.</li></ul><h3 id="_6-compile-time-embedding-remains-the-primary-path" tabindex="-1">6. Compile-time embedding remains the primary path <a class="header-anchor" href="#_6-compile-time-embedding-remains-the-primary-path" aria-label="Permalink to “6. Compile-time embedding remains the primary path”">​</a></h3><p>For the canonical kit and any kit known at build time, <code>include_str!</code> + compile-time assembly remains the path. The cache is for <strong>runtime-loaded</strong> languages only. A compile-time-embedded <code>Language</code> is already &quot;cached&quot; in the binary; the runtime cache adds nothing.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>ADR-0044 §6 made authored data files canonical and embedded them at compile time via <code>include_str!</code>. This is compile-time caching: zero runtime parse cost, zero I/O. It works for the canonical kit and any kit known at build time.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Runtime-loaded languages are fast on repeat loads.</strong> The first load</li><li><strong>No silent drift.</strong> The cache key includes every input that affects the</li><li><strong>Compression reduces I/O and binary size for cached artifacts.</strong> Modest</li><li><strong>The authored source stays inspectable.</strong> Compression applies only to the</li><li><strong>Cache key computation has a cost.</strong> Hashing every fragment source on</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0065-derived-artifact-cache-and-compression.html"><code>design/0065-derived-artifact-cache-and-compression.md</code></a>.</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};